from course_common import Course
S={
 'think':('Stanford Encyclopedia · Critical Thinking','https://plato.stanford.edu/entries/critical-thinking/'),
 'logic':('Stanford Encyclopedia · Classical Logic','https://plato.stanford.edu/entries/logic-classical/'),
 'know':('Stanford Encyclopedia · Epistemology','https://plato.stanford.edu/entries/epistemology/'),
 'self':('Stanford Encyclopedia · Personal Identity','https://plato.stanford.edu/entries/identity-personal/'),
 'free':('Stanford Encyclopedia · Free Will','https://plato.stanford.edu/entries/freewill/'),
 'virtue':('Stanford Encyclopedia · Virtue Ethics','https://plato.stanford.edu/entries/ethics-virtue/'),
 'duty':('Stanford Encyclopedia · Deontological Ethics','https://plato.stanford.edu/entries/ethics-deontological/'),
 'result':('Stanford Encyclopedia · Consequentialism','https://plato.stanford.edu/entries/consequentialism/'),
 'justice':('Stanford Encyclopedia · Distributive Justice','https://plato.stanford.edu/entries/justice-distributive/'),
 'confucius':('Stanford Encyclopedia · Confucius','https://plato.stanford.edu/entries/confucius/'),
 'dao':('Stanford Encyclopedia · Daoism','https://plato.stanford.edu/entries/daoism/'),
 'beauty':('Stanford Encyclopedia · Beauty','https://plato.stanford.edu/entries/beauty/'),
 'meaning':('Stanford Encyclopedia · The Meaning of Life','https://plato.stanford.edu/entries/life-meaning/')}
c=Course('philosophy',S);C=c.C;O=c.O
c.chapter('把问题问清楚','先分清概念、事实与价值，再认真讨论。','能把含糊争论改写成可讨论的问题。',['think'])
C('概念澄清','大家说的自由，是同一种自由吗？','两位朋友争论“选课自由”：一人指没人禁止，一人指有时间和费用才能选。哪种分析更能推进讨论？','分歧：先区分不受阻拦与实际选择能力|行动：分别追问两种自由需要什么条件','分歧：认定两人只是性格不同|行动：继续重复“自由最重要”','先辨明同一个词的不同用法，才知道在争论什么；澄清概念本身还没有决定哪种自由更重要。')
C('事实与价值','有很多人喜欢，就说明应该推广吗？','有人说一种活动很受欢迎，所以学校应该投入全部社团预算。哪种分析指出了尚缺的理由？','事实：受欢迎说明某种偏好|价值桥梁：还要说明为何流行应优先于其他需求','事实：受欢迎说明某种偏好|结论：人数多自然等于道德上应该优先','从事实到“应该”还需要价值前提与资源取舍，不能只靠受欢迎程度。')
C('定义与反例','给“游戏”下定义，需要检查什么？','小禾把游戏定义为“有输赢的活动”。哪种回应更能检查这个定义，而不是评价她本人？','反例：合作探索、没有最终输赢的玩法是否也算游戏？|追问：定义想覆盖日常用法还是特定比赛？','反例：小禾从来不玩，所以她不懂|追问：换一个资历更老的人宣布答案','用边界案例检查定义的覆盖范围，比攻击提出者更能推进讨论。定义也可能服务不同目的。')
C('问题层次','怎样回答“AI 会思考吗”？','面对这个问题，哪份讨论起点更清楚？','概念：思考指计算、推理还是主观体验？|证据：分别说明哪类行为能支持哪种判断','概念：回答像人就一定有人的全部体验|证据：只挑一句流畅回答就结束讨论','先拆开能力和体验等不同问题，再寻找相应证据；行为相似并不独自解决全部心灵问题。')
O('问题改写','把一句争吵变成三个问题','同学讨论“短视频让人变笨”，各自拿一段经历互相反驳。','把这句话拆成概念、经验事实和价值判断三个问题，说明各自需要什么材料。','可先说明“变笨”指注意持续、记忆还是判断能力，再问特定使用方式是否影响它们，最后讨论什么习惯值得选择。个人经历可形成线索，不能直接代替全部证据。','原话：短视频让人变笨|分歧：有人学到技能，有人觉得难以专注|条件：未说明内容类型与使用时间')
O('边界案例','友谊一定要求每天联系吗？','一位朋友认为很久不联系就不算朋友，另一位朋友长期异地仍彼此信任。','提出一个暂定的友谊标准，用至少一个边界案例检查，并说明你愿意怎样修改。','可以把关心、信任与愿意回应需要作为标准，再用不常联系的老友或每日聊天却互不关心的人检验。标准不必唯一，关键是说明它解释了什么、遗漏了什么。','案例甲：一年才见面，但遇到困难会认真帮助|案例乙：每天聊天，但从不关心对方处境')
O('隐含前提','这句话中，藏着哪一步？','小组有人说：“这本书很难，所以它一定更值得读。”','找出隐含前提，提出一种反例，并写一个更有限的结论。','隐含前提是难度越高价值越高。混乱写作也可能很难，而清楚的入门书也可能很有价值。可改为难度有时对应新概念，需要结合学习目标、论证和已有基础判断。','已知：这本书读起来很难|未给：内容质量、个人目标和基础|结论：一定更值得读')
O('讨论规则','给一次分歧订一份讨论约定','读书会里，一位成员每次都用“这是我的感受”结束所有追问，另一位则否定感受有讨论价值。','提出三条可执行的讨论约定，既保留体验，也允许追问理由与适用范围。','可以约定先复述、区分体验报告和一般断言、用反例检查推广范围；个人体验值得听，但“我这样感受”不自动证明所有人都如此。讨论目标是理解与改进理由，不是强迫一致。','场景：六人读书会|问题：个人感受与普遍主张混在一起|目标：能继续讨论而不攻击个人')
c.chapter('理由怎样支撑结论','区分推理有效、前提可信与常见论证错误。','能重建简单论证并用反例检验。',['logic','think'])
C('有效与可靠','推理形式正确，就一定可信吗？','论证：所有猫都会飞；团团是猫；所以团团会飞。哪种评价更准确？','形式：若前提都真，结论就必须真|问题：第一个前提事实上不可信，因此不是可靠论证','形式：结论听起来荒谬，所以任何推理形式都错误|问题：无需区分前提与形式','形式有效与论证可靠需要区分；这个形式有效，但包含假的前提，不能凭它相信结论。')
C('肯定后件','地面湿了，就一定下雨了吗？','已知“如果下雨，地面会湿”，现在看见地面湿。选择更合理的判断。','可能：下雨能解释地面湿|限制：洒水等原因也能使地面湿，不能必然推出下雨','可能：只要地面湿就证明下过雨|限制：不需要查看其他原因','由“如果 P 则 Q”和 Q 不能必然推出 P；需要检查其他使 Q 成立的可能。')
C('论证重建','反对者真的主张禁止一切吗？','甲建议图书馆夜间减少外放。乙回应“你要禁止所有人交流”。哪种分析更公平？','复述：先回应夜间外放的具体限制|反驳：可讨论执行成本、例外与替代方案','复述：把甲说成禁止一切交谈|反驳：只攻击这个更极端的立场','把对方主张改成容易攻击的极端版本，没有回应原论证。可先准确重建再反驳。')
C('相关理由','提出者迟到过，就能否定时间表吗？','某人提出新排班方案，但他上周迟到。哪种审查更直接相关？','检查：时间表能否覆盖实际任务和休息需求|区分：迟到可能影响执行信任，但不直接证明方案无效','检查：指出他本人曾迟到|结论：时间表每一项都必然错误','提出者的行为可能与可信度或执行有关，但方案是否合理仍需检查具体理由。')
O('前提与结论','把一段话整理成论证','“应该延长图书馆开放，因为很多人晚上才下班，现有时段让他们无法借书。”','列出事实前提、价值前提和结论，并指出一种会改变判断的新信息。','事实是部分人晚间无法借书，价值前提可以是公共服务应兼顾不同时间安排；结论是延长或调整时段。人员、安全与替代服务会影响方案，应检查而不是自动否定目标。','陈述：下班后借不到书|诉求：延长开放|未知：人数、成本与替代服务')
O('反例检验','怎样推翻“只要努力就会成功”？','朋友把自己的成功经验总结为“所有努力的人都会成功”。','区分“努力有帮助”与“努力足够保证成功”，给出反例并提出较合理的表述。','有人努力仍受资源、机会或健康限制，可反驳保证成功的全称断言；它并不证明努力毫无作用。可说在特定任务和条件下，合适努力可能提高成功机会。','命题：所有努力的人都会成功|经验：提出者确实付出并取得成果|遗漏：条件差异与未成功案例')
O('归纳强度','三次准时，就能放心永远准时吗？','你连续三次乘坐同一公交都准时到达，想据此安排一次不能迟到的考试行程。','说明这些经历支持什么、不支持什么，再提出一个与风险相称的安排。','经历能形成有限期待，不能证明永远准时。可补查更长时段和当天情况，给重要行程留缓冲；谨慎程度取决于迟到代价，不必要求日常行动都有绝对确定性。','样本：三次乘车|任务：重要考试|未知：路况、时段与偶发故障')
O('最强回应','替反对者把理由说完整','你赞成学校开设手机存放区，同学担心紧急联系不便。','先用对方愿意认可的方式重述顾虑，再回应一个最强理由，并说明自己方案要修改哪里。','可以承认紧急可联系性是正当要求，再讨论备用联络、例外和自愿使用。不要把顾虑说成“只想玩手机”；能够容纳合理反对理由的方案通常更可讨论。','立场：减少上课分心|反对：担心紧急联络|约束：不能假定所有人有同样家庭安排')
c.chapter('我们凭什么知道','在相信、知识、证据与怀疑之间找位置。','能区分支持程度，按证据调整相信。',['know'])
C('真信念与知识','猜对了，就算知道吗？','小安随便猜明天的列车晚点，结果碰巧猜中。哪种分析更谨慎？','判断：猜测恰巧为真|追问：它缺少什么可靠根据，是否足以称为知道？','判断：只要结果为真就掌握了知识|追问：以后都可以用同样办法作决定','猜中与有根据地知道不同；知识的完整定义存在争论，本题只检查偶然真与理由的区别。')
C('证词与核验','有名的人说过，就不必查了吗？','一位演员介绍天文现象，视频没有说明来源。哪种核验更相关？','查证：寻找原始观测或相关领域资料|态度：身份可提供线索，仍需核对具体主张','查证：名气足够大就无需材料|态度：质疑来源等于不尊重本人','名气不自动构成某一领域的知识根据；应检查专长、出处与可核对材料，也不必因演员身份就一概否定。')
C('可修正的相信','发现新证据，改口就是不坚定吗？','你原以为展览免费，后来看到正式公告：部分区域收费。哪种更新合理？','更新：区分免费区与收费区，修改原判断|说明：新材料怎样改变原来支持程度','更新：为了前后一致继续说全部免费|说明：坚持原话比检查公告重要','根据更相关的新证据修正相信，是认真求知的一部分；还应核对公告日期和适用范围。')
C('怀疑的分寸','不能百分之百确定，就什么都不能信吗？','有人认为视觉偶尔会误导，所以连眼前桌上有杯子都不能在日常中相信。选择更审慎的回应。','区分：逻辑上可能出错与日常有充分理由不同|行动：按风险与可核验性调整确信程度','区分：可能出错意味着所有看法同样可信|行动：证据之间不再需要比较','承认感知可错不意味着一切证据等价；怀疑需要说明范围和标准，而不抹平支持程度差异。')
O('支持程度','这张截图值得相信到什么程度？','朋友转来一张没有日期和原链接的活动取消截图。你正准备出发。','说明当前可暂信什么、还需要核对什么，以及怎样向同行的人表达不确定性。','截图是一条待核线索，可以查主办方当前公告或联系场地；向同行说明尚未确认、何时再决定。不要把“未核实”说成必然虚假，也不把转发次数当确认。','材料：无日期截图|决策：今天是否出发|可核对：主办方与场地')
O('解释与证据','为什么总能“应验”的说法难检查？','某人声称护身石有用：顺利就是生效，不顺利就是挡掉更大的灾难。','说明这个说法怎样处理所有结果，提出能使主张接受检验的条件，并区分检验与个人安慰。','若任何结果都被视为支持，就难用经验区分有用与无用。可以先明确“有用”的具体含义和什么结果会削弱主张；提供安慰与改变外部事件是两类不同主张。','成功解释：护身石生效|失败解释：避免了更大失败|问题：什么结果会让提出者修改判断？')
O('观察与解释','看到排队，能知道店一定好吃吗？','一家新店门前长队，但你不知道是不是发赠品、出餐慢或确实受欢迎。','列出观察事实与两种解释，说明怎样获得能区分解释的新材料。','事实是某时刻有队伍；好吃、促销和出餐慢是不同解释。可看是否有促销、等待与出餐速度、不同时间的情况，并询问真实体验；单一线索不足以锁定唯一原因。','观察：门前有人排队|未知：促销、服务速度和口味评价|任务：决定是否值得尝试')
O('证据责任','别人不能证明错，就等于我说对吗？','有人说某种看不见的力量决定每次抛硬币，理由是别人无法证明没有。','说明不能反驳与已经获得支持的区别，并给出你愿意继续讨论的证据条件。','无法证明不存在不等于已有存在证据。可以请提出者说明预测、独立观察或与其他解释的差异；若没有可区分条件，可承认讨论的限制，而不伪装已经证伪。','主张：不可见力量决定结果|依据：别人不能证明没有|边界：没有独立观察材料')
c.chapter('自我、选择与责任','思考同一性、行动控制与责任的条件。','能区分解释行为、理解处境与评价责任。',['self','free'])
C('同一性的标准','旧船换完木板，还算原来那艘吗？','维修后每块木板都换过。哪种讨论更能呈现问题，而不假装已有唯一公认答案？','标准：分别比较材料连续、结构连续与使用历史|分歧：说明采用哪种标准以及理由','标准：只要名字相同就逻辑上必定同一|分歧：其他标准都无需讨论','思想实验让不同同一性标准发生张力；选择标准需要理由，不能只宣布一种日常习惯解决所有情形。')
C('控制与强迫','两次相同动作，责任一定一样吗？','甲自愿交出钥匙，乙在明确威胁下交出钥匙。哪种分析更充分？','比较：外部动作相同，但选择条件不同|评价：考察胁迫程度、可行替代与知情情况','比较：只看钥匙离手这一结果|评价：责任必须完全相同','责任评价常与控制、知情和可行替代有关；理解胁迫并不要求否定所有责任讨论。')
C('决定论与宿命','如果行为有原因，就不用做决定了吗？','有人说一切行动都有原因，所以思考计划不会有任何作用。选择更有根据的分析。','区分：决定论与无论做什么结果都相同不是一回事|作用：思考、计划本身也可能是因果过程的一部分','区分：既然有原因，选择过程就完全不存在|作用：任何计划都不会影响未来','行为有因果解释，不自动推出行动和计划没有作用；这仍没有解决自由意志争论的全部问题。')
C('解释与辩护','理解原因，就等于赞成行为吗？','同学因长期被排挤而在群里辱骂别人。哪种回应区分了不同任务？','理解：认真了解处境与行为原因|评价：仍可讨论伤害、责任和更好的回应','理解：一旦解释了原因就必须认为行为正当|评价：不再考虑被辱骂者','解释行为为何发生、体谅处境与判断行为是否正当不同，可以同时理解背景并讨论责任。')
O('人格连续性','失去一段记忆，还是不是我？','一个人失去了几年前的记忆，却保持许多关系、习惯与身体连续性。','选两种“还是同一个人”的标准，说明各自解释力与困难，不要求给医学判断。','可以比较身体连续性与心理联系：前者保留生物个体，后者关心记忆、性格和意向；记忆不完整提醒我们心理联系也可能有不同程度。题目是概念比较，不能据此诊断真实个体。','保留：身体、部分习惯和人际关系|变化：一段自传记忆缺失|问题：同一性的不同含义')
O('自主与影响','推荐算法懂我，选择还算我的吗？','你发现自己大多只看平台推荐，很少主动搜索；仍能关掉推荐和寻找别的内容。','区分受影响、被操纵与有选择能力，提出一个能增加自主性的具体做法及其限制。','受影响不等于完全失去自主，但默认、信息不对称和习惯可能缩小实际选择。可以主动订阅、搜索反面材料、设定使用时段；这些做法增加反思空间，不证明人能完全不受环境影响。','情境：主要依赖推荐|可选：搜索、订阅和离开|未知：系统影响程度与个人目标')
O('责任程度','一个错误，怎样比较责任？','甲事先被清楚告知风险仍忽视，乙获得的说明有关键遗漏，两人造成相同损失。','说明相同结果是否足以判定相同责任，并列出要了解的三类事实。','应考察知情、可控制程度、可行替代和角色义务。相同损失不独自决定同等责任；遗漏由谁造成、乙是否有合理核查机会也影响判断，不宜仅凭摘要定罪。','甲：已知风险仍忽视|乙：关键信息未被告知|共同：造成相同损失')
O('反思选择','写给未来自己的一个承诺','你想每天学习，却总在疲惫时取消计划。有人说“真实的你就是当下最想做的事”。','比较即时愿望与长期认可的目标，提出一种尊重两者的安排，并解释它为什么仍需要反思。','可以区分一时冲动和反思后认可的愿望，安排较短学习与必要休息。长期目标也未必天然更真实，应检查是否出于自己认可、是否可持续，不能把疲惫简单说成道德失败。','愿望一：当下休息|愿望二：长期掌握技能|约束：精力有限，目标可能需要调整')
c.chapter('面对道德两难','比较后果、义务与品格，承认理由之间的张力。','能解释不同伦理视角怎样改变关注点。',['virtue','duty','result'])
C('伦理视角','同样帮助别人，理由可以不同吗？','三人都愿意帮助迷路者。哪种比较更准确？','比较：有人重视减少痛苦，有人重视助人义务，有人重视仁厚品格|边界：视角不同不意味着只能关注一个维度','比较：只要行动一样，理由就没有任何区别|边界：伦理学只需要记录最终动作','相同行动可能有不同理由。伦理视角的重点可以不同，也可能同时考虑后果、义务与品格。')
C('后果与边界','整体收益高，就不用考虑任何人吗？','社团准备公开某成员的私信以增加募捐，未征得同意。哪种分析更充分？','后果：考虑募捐收益与可能伤害|边界：讨论隐私、同意和是否有替代方法','后果：只要预计善款多，其他理由都自动失效|边界：不必考虑当事人','预计收益是理由之一，但不能未经论证就抹除同意、权利和其他方案；还应检验预测。')
C('义务冲突','承诺总能机械执行吗？','你答应按时赴约，却在途中遇见需要紧急求助的人。选择更认真处理冲突的分析。','冲突：守约与援助都构成理由|行动：比较紧急程度、替代帮助并尽快说明','冲突：一句“必须守约”足以结束所有讨论|行动：情境与可用替代都无关','承认义务不等于忽略义务之间的冲突；可以说明优先理由、可行替代和如何补偿失约。')
C('品格与情境','一次勇敢举动，就能确定完整品格吗？','某人一次冒险帮助他人，有人据此判断他在任何情境都一定勇敢。哪种评价更谨慎？','观察：这次行为可以体现勇敢|限制：稳定品格还需看动机、判断与不同情境','观察：一次行为足以证明永远如此|限制：不必区分勇敢与鲁莽','品格判断需要比单次外部动作更多的依据；勇敢还涉及对风险和理由的适当判断。')
O('多视角比较','一次善意隐瞒，怎样分析？','朋友询问你对他作品的看法，你担心直说缺点让他难过，却也知道他希望改进。','分别从后果、诚实义务或关系品格中选两个视角，提出回应，并说明代价。','可以用具体、温和且真实的反馈兼顾改进与关系；也可先问他需要哪种反馈。两种视角可能支持相似做法，关键在解释理由，不把善意当所有谎言的许可。','事实：朋友主动求反馈|顾虑：情绪与改进可能冲突|未知：反馈用途与承受方式')
O('利益相关者','谁的损失被漏掉了？','校园活动用一次性装饰制造很好的现场效果，参与者开心，清理人员加班，废弃物显著增加。','列出受影响者，比较两种替代方案，并说明你如何权衡看得见与不易看见的影响。','可以把参与者、清理人员、后续使用者和环境影响纳入，比较可重复材料、缩减规模或共同清理；说明代价和分担，不要求某一种结论才算正确。','收益：现场体验|代价：清理劳动与废弃物|替代：可重复材料或不同布置')
O('可普遍化的理由','我可以例外，因为是我吗？','一位成员希望自己不用轮值，理由只是“我不喜欢”，但认为别人仍应照常完成。','解释这个理由能否一致地用于他人，提出一种可能正当的例外条件。','仅因是自己而例外缺少可一致适用的理由。健康、照护或能力限制可能支持调整，前提是标准能解释相关差异并公平分担；公平不必等于所有任务完全相同。','规则：成员轮值|申请：只因不喜欢要求例外|问题：哪些差异与分工相关？')
O('判断与不确定性','没有完美方案，怎样负责任？','活动延期会让远途参与者损失，继续又存在尚未弄清的安全隐患。','说明需要哪些信息、怎样处理不确定风险，以及决定后应怎样解释和补救。','先核查风险程度与专业意见，比较延期、缩减或取消的可行性，及时告知并考虑受影响者补救。负责任不等于保证零损失，而是给出相称理由、透明沟通并承担后果。','选择：继续、延期或缩减|未知：风险严重程度|影响：安全、时间与已投入成本')
c.chapter('公正与共同生活','在平等、需要、贡献与程序之间作比较。','能给分配规则和公共讨论提供可公开的理由。',['justice','think'])
C('分配标准','每人一份，就一定公平吗？','社团分配交通补助，成员住得远近、经济条件与任务负担不同。哪种分析更清楚？','比较：平均分、按需要和按任务各有理由|要求：先说明补助目标，再解释相关差异','比较：所有场景都只能平均分|要求：任何需求差异都与公平无关','公平可能涉及平等、需要、贡献和机会等标准；应先说明分配目标和相关差异。')
C('程序与结果','抽签公开，就自动解决公平了吗？','两个社团抽签分场地，但一个只有现场活动可做，另一个还有多种替代空间。选择更完整的评价。','程序：公开抽签减少部分偏袒|结果：仍可问参与资格、需要和替代机会是否合理','程序：抽签公开，所以所有规则必定公正|结果：不必检查谁被纳入或排除','公平程序有价值，但程序设计、初始条件与结果负担仍可讨论。')
C('多数与少数','票多，就可以忽略一切反对吗？','多数人赞成把安静自习室改成活动室，少数人没有其他可用自习空间。哪种讨论更充分？','承认：多数偏好是公共决策材料|补充：考虑少数的基本需要、替代与协商','承认：多数通过等于没有任何损失值得解释|补充：反对者只能退出','多数决是一种程序，不自动消除少数利益与基本需要的理由；应公开解释并寻求可行安排。')
C('形式机会与实际条件','报名都开放，机会就完全相同吗？','课程免费开放报名，但只在工作日上午线下进行。哪种分析更能识别实际限制？','形式：没有限制谁能报名|实际：时间、交通和照护条件影响可达性','形式：报名按钮对所有人可见|实际：因此参与条件完全相同','形式上相同的规则可能带来不同的实际机会；怎样改善还需结合资源、目的与代价。')
O('规则设计','怎样分配最后两张工作台？','四人希望使用两张工作台：有人有截止任务，有人已使用很久，有人没有替代设备。','提出一套可说明的规则，比较至少两种公平标准，并给出申诉或修正办法。','可结合截止紧迫、既往占用和替代条件安排时段，说明为何某些差异相关；提供公开申请与复核。不是哪套分配数字固定正确，而是理由一致且考虑受影响者。','资源：两张工作台|需求：紧迫性与替代不同|历史：使用时长不同')
O('立场交换','不知道自己位置时，你会怎样定规则？','班级决定小组展示的评分与帮助机制，成员能力和家庭资源差异明显。','暂时不知道自己会处在哪个位置，提出规则，再说明这种思考方法能帮助什么、不能保证什么。','可优先保证基本资源、清楚标准和合理支持，再讨论努力与成果怎样评价。立场交换能减少只为自己设计的偏见，但人们对风险、需要和公平仍可能有合理分歧。','差异：设备、时间和经验|共同目标：学习与合理评价|限制：支持资源有限')
O('公共理由','怎样讨论一条你不喜欢的规则？','社区夜间活动影响休息，但参与者也需要工作后共同活动的空间。','为双方重建一个合理理由，提出折中或替代，并解释为什么可向不同立场的人说明。','休息与共同活动都有理由，可讨论时段、音量、地点及试行复盘。不要把一方说成自私或懒惰；折中是否可行还要听受影响者并核查环境。','甲：需要安静休息|乙：工作后才有共同活动时间|可能：时间、地点与音量调整')
O('平等与照顾','帮助更多，需要被解释吗？','一位新成员需要更多培训时间，老成员认为每人支持时长必须一样。','比较同等尊重与相同时长，说明怎样回应新成员需要并公平分担支持劳动。','尊重相等不必要求资源完全相同；更多帮助可能让实际参与机会接近。还需说明培训目标、支持边界和承担者的时间，避免把包容成本默默压给少数人。','新成员：缺少基础培训|老成员：担心劳动分担|目标：每人都能真实参与')
c.chapter('从中国哲学进入日常','在关系、修养与不同生活路径中提出问题。','能联系语境理解概念，避免把传统压成口号。',['confucius','dao'])
C('仁与礼的关系','形式周到，就一定照顾到了人吗？','聚会礼节齐全，却没人注意到一位来宾无法参与。哪种分析更适合作为儒家关系伦理的入门讨论？','讨论：礼的形式怎样表达尊重与关怀|检查：具体的人是否被真正照顾，形式是否需要调整','讨论：动作完全照旧就是全部道德要求|检查：无需关心当事人的处境','可把礼理解为需要关怀与修养支撑的实践，而不把它缩成机械动作；儒家内部也有解释差异。')
C('修养与反思','改过，是背一句话还是改行动？','小林每天背诵“尊重他人”，开会时却总打断别人。哪种学习安排更能联系修养？','实践：观察自己何时打断，尝试先听完并复述|反思：请同伴反馈，持续调整具体行为','实践：增加背诵次数即可|反思：是否尊重只取决于口号是否熟练','修养可以通过具体关系中的行动、反思和练习来讨论，不能只由口号熟练程度判断。')
C('无为与强制','无为，就是任何事都不做吗？','园丁比较两种养护：了解植物习性后适度照料，与完全不管。哪种比喻更能避免把道家无为简单化？','理解：减少违背条件的强制和过度干预|边界：仍可有细致观察与适当行动','理解：任何行动都违反无为|边界：不必观察具体条件','无为有多种历史解释，不能机械等于懒散或完全停止行动；此处只以减少强制的适切行动作入门比喻。')
C('视角与边界','看见视角不同，就什么都一样了吗？','同一棵树，木工看材料，路人看树荫。哪种延伸更谨慎？','启发：目的影响我们注意什么|边界：不同视角仍可在具体问题上比较理由与事实','启发：既然视角不同，所有说法同样真实|边界：不必检查树的实际情况','视角多样提醒我们反思标准和用途，不自动推出所有事实判断等价，也不能代替具体论证。')
O('关系中的关怀','一份礼貌，怎样变成真实尊重？','你为长辈安排活动，却从未询问他是否喜欢，只按“对长辈好”的惯例决定。','提出一次兼顾关系、倾听与适当礼节的修改，说明怎样避免替对方定义全部需要。','可先询问偏好与实际能力，保留表达敬意的方式，同时允许拒绝或改期。关系中的关怀不等于包办；不同家庭语境可有不同表达，需说明具体理由。','出发点：表达敬意|遗漏：当事人的偏好|限制：时间和安排已部分确定')
O('习惯与修养','选择一个能观察的改变','你希望待人更耐心，但“变成更好的人”太模糊，难以回看。','选择一个日常场景，提出可重复练习、反思和接受反馈的安排，并说明不能仅靠次数衡量的部分。','可练习开会先听完再复述，每周回看一次误解并请同伴举例。次数能记录实践，不能独自证明关怀与判断已经成熟；修养也应面对具体情境。','目标：更耐心地对话|场景：小组开会|材料：可记录自己的行动，不给别人贴标签')
O('适切行动','什么时候多做反而帮倒忙？','朋友正在学习做饭，你不断替他完成每一步，结果他始终没有机会尝试。','借“减少过度干预”的思路安排支持，说明何时退后、何时仍要介入，不把比喻当万能原则。','可以先询问需要，只在必要提示和安全边界处介入，让对方尝试并复盘。减少控制不等于放任危险；这个比喻只帮助讨论支持与自主，不能代表道家所有观点。','意图：帮助朋友|现状：你替他完成大部分步骤|风险：自主练习与安全都需要考虑')
O('比较而非贴标签','两种传统，怎样认真地放在一起？','有人把儒家概括为“只讲服从”，把道家概括为“只讲躺平”，准备据此选择人生道路。','指出这种概括漏掉什么，选择一个具体问题比较两种视角，并说明还需阅读什么。','可围绕如何帮助朋友比较关系责任与适切干预，承认内部多样性和历史语境；继续回到具体文本、注释与不同解释，而不把传统变成性格测试。','口号一：儒家等于服从|口号二：道家等于躺平|任务：选择具体问题，而非给人分类')
c.chapter('意义、审美与认真对话','让生活判断有理由，也留出分歧与继续追问的空间。','能表达立场、回应反例，并承认判断限度。',['meaning','beauty','think'])
C('偏好与评价','“我不喜欢”与“它毫无价值”一样吗？','你不喜欢一幅画的颜色，朋友认为它表达了一段复杂经历。哪种讨论更清楚？','区分：个人喜好与作品价值评价|追问：形式、语境和表达提供了什么理由','区分：只要我不喜欢，作品就毫无价值|追问：别人的理解不值得听','喜好是重要体验，但更广的审美评价还可讨论形式、表达和语境；也不必因了解背景就强迫喜欢。')
C('意义与快乐','有意义的事，必须每刻都快乐吗？','照护家人可能疲惫，练习一项技能也常枯燥。哪种分析避免把意义与即时愉快完全等同？','比较：愉快、关系、投入和价值可能不同|边界：不把所有痛苦自动说成有意义','比较：只要当下不开心就完全无意义|边界：无需看长期认可与关系','意义与愉快可能关联但不必等同；反过来痛苦本身也不是意义的保证，仍需讨论价值与选择。')
C('善意理解','真正回应分歧，先做什么？','朋友说他更重视安静生活，你认为应不断挑战。哪种回应更有助于理解？','复述：先问清安静对他意味着什么|回应：讨论可能得到和失去的东西','复述：直接说他害怕成长|回应：只用自己的生活目标给他下结论','先澄清对方实际价值和处境，才能回应其最强理由；理解不要求放弃自己的立场。')
C('判断可修正','好的结尾，必须把一切定死吗？','读书会讨论后仍有分歧。哪种记录更能继续推进？','记录：当前立场、最强理由和未解决反例|后续：说明什么新材料会让自己修改','记录：为了显得坚定删除所有疑问|后续：不允许任何条件改变判断','清楚的暂定结论与开放问题可以同时存在；承认限度不等于没有立场。')
O('审美理由','为一个审美判断多说一步','朋友问你为什么喜欢一段很安静的电影，你只回答“有感觉”。','描述一个具体形式或观看经验，说明它怎样支撑你的评价，再回应一种不同的合理感受。','可指向停顿、画外声与人物动作如何让你留意关系；别人感到缓慢也有可理解的依据。说明体验与形式的联系，比宣布某类电影永远更高级更可讨论。','作品：安静、长停顿的片段|你的体验：被吸引|不同体验：有人觉得缓慢')
O('生活价值','两条生活道路，怎样比较？','甲有稳定工作和很多陪伴时间，乙选择不稳定但投入的创作。两人都认可自己的选择。','选两种价值维度比较，提出一条对双方都公平的追问，不以收入或忙碌独自给人生排序。','可比较自主、关系、创造和安全感，问是否反思认可、代价是否可承受、是否尊重他人。不同价值可能无法完全换算；不据此推出所有选择没有优劣可谈。','甲：稳定与陪伴|乙：创作与不确定|共同：都在反思自己的生活')
O('立场与反例','给自己的判断找一个强对手','你主张“任何时候都应说出全部真相”，现在要认真检查它。','重建支持理由，提出一个强反例，形成可解释的修正版或说明为何仍保留原立场。','可先说明诚实对信任的价值，再考虑隐私、求助安全或尚未核实的信息；修正为在适当关系与情境中真实而负责地沟通。也允许坚持更强义务，但须回应反例而不是跳过。','立场：任何时候说出全部真相|支持：信任与诚实|检查：隐私、伤害与知情责任')
O('综合论证','把一段“我觉得”写成小论证','你可以选“学校应不应该设无手机时段”或另一个具体生活问题，写一次认真判断。','给出立场、两条理由、一个最强反对意见和回应；说明至少一个会使你改口的条件。','合格表达可以赞成、反对或有条件支持，只要概念清楚、理由相关并认真回应异议。不按世界观方向判分，练习检验的是本次论证质量。','可选：无手机时段或自选具体问题|要求：理由与反例|边界：事实与价值前提应分开')
